from g_common import *

# --------------------------------------------------------------------------- FINANCE

def finance_body():
    flow = ('<div class="flow">'
            '<div class="box"><b>BizBox</b>the finance system</div><span class="arrow">→</span>'
            '<div class="box"><b>sync-bizbox</b>read-only copy</div><span class="arrow">→</span>'
            '<div class="box"><b>The mirror</b>on the desk</div><span class="arrow">→</span>'
            '<div class="box"><b>Your work</b>tickets, projects, agreements</div></div>'
            '<div class="flow"><div class="box"><b>A change you propose</b>on a mirrored record</div><span class="arrow">→</span>'
            '<div class="box"><b>Changes to BizBox</b>waits, recorded</div><span class="arrow">→</span>'
            '<div class="box off"><b>The writer</b><span class="planned">planned</span></div><span class="arrow">→</span>'
            '<div class="box off"><b>BizBox</b>not written today</div></div>')
    return "".join([
        HERO("Finance on Dada PSA", "Agreements made on the desk, and BizBox's purchase orders, products and invoices "
             "mirrored beside the work they pay for. How to read it, link it, cover it, and propose a change to BizBox, "
             "including the two-way link that is designed but not yet switched on.",
             ["For finance staff and service managers", "Finance module", "About 15 minutes"], "orange"),
        S("fin-what", "Start here", "What Finance is, and what it is not",
          LEAD("BizBox is PMC's finance system. It stays the place where money is recorded. Dada PSA reads a copy of what "
               "BizBox holds, so the desk can put a purchase order or an invoice next to the ticket or project it paid for."),
          flow,
          GRID([("Read-only mirror", "Purchase orders and their lines, products, invoices, and agreements when BizBox has them. Copied by <code>sync-bizbox</code>; nothing on the desk edits them."),
                ("Agreements, on the desk", "BizBox holds no supplier agreements, so the desk keeps them: a name, the other party, a term, a status and an amount, and the BizBox records each covers."),
                ("Links to work", "A ticket or project names the BizBox records it concerns. The link is the desk's own data; BizBox never sees it."),
                ("Proposed changes", "A person with Finance Write can propose a change to a mirrored record. It waits, recorded. BizBox is not written to today.")]),
          NOTE("warn", "<b>Dada PSA issues no invoice and writes nothing to BizBox.</b> Every figure on these pages is BizBox's own, as of the last sync shown at the top of Finance."),
          CHOOSER("Where does this live?", [
              ("inv", "An invoice", "<b>In BizBox.</b> The desk shows a read-only copy under Finance › Invoices. Its status is BizBox's own word: Draft, Posted or Cancelled. Whether it is paid is not something BizBox's tables tell the desk, so the desk never says so."),
              ("po", "A purchase order", "<b>In BizBox,</b> with its lines. The desk shows each line's ordered and received quantities, unit cost and extended total, under Finance › Procurement."),
              ("agr", "A supplier agreement", "<b>On the desk.</b> Created under Finance › Agreements (or drafted by a won sales opportunity). It names the BizBox invoices, purchase orders and products it covers."),
              ("link", "Which ticket a PO paid for", "<b>On the desk.</b> The ticket's Finance card, or the project's Finance card, links the record. Only people who can see that ticket or project see the link."),
              ("chg", "A correction to a BizBox record", "<b>Proposed on the desk, made in BizBox.</b> The proposal waits under Changes to BizBox until someone makes the change in BizBox (and marks it done), or until the planned write path is switched on.")]),
          who=["Everyone with Finance"]),
        S("fin-who", "Start here", "Who can do what",
          LEAD("Finance is one of the desk's security modules. Your security role gives it a level; the level decides what you see and do. Sales uses the same level."),
          WIDGET("Try a level", '<div class="w-row"><label>Your Finance level<select><option>NONE</option><option selected>READ</option><option>WRITE</option><option>ADMIN</option></select></label></div><div class="out"></div>',
                 "perm", {"none": "Finance and Sales are not in your top bar, and their pages refuse you.",
                          "actions": [["See Finance: agreements, procurement, products, invoices, changes", "READ"],
                                      ["See Sales: the pipeline, opportunities and quotes", "READ"],
                                      ["Link a BizBox record to a ticket you work (you also need Work on its board)", "READ"],
                                      ["Create and edit agreements; make active, inactive or cancel", "WRITE"],
                                      ["Cover invoices, purchase orders and products from an agreement", "WRITE"],
                                      ["Propose a change to a BizBox record, or cancel one", "WRITE"],
                                      ["Create opportunities and quotes, move stages, send and accept quotes", "WRITE"]]}),
          TABLE(["Starter role", "Finance level"], [["Technician", "Read"], ["Service manager", "Write"], ["Read only", "None"]]),
          NOTE("info", "Which roles hold Finance Write is Dada's decision, set in Setup › Security roles. The starter roles are only a starting point."),
          who=["Everyone with Finance", "Administrators"]),
        S("fin-page", "Reading Finance", "The Finance page",
          LEAD("Five tabs, one list each. The banner at the top says when BizBox was last copied, by whom, and what changed."),
          TOUR("fin-procurement"),
          TABLE(["Tab", "What it lists", "Columns"],
                [["Agreements", "The desk's own agreements", "Agreement, Name, Party, Starts, Ends, Status, Amount"],
                 ["Procurement", "BizBox purchase orders", "PO, Vendor, Ordered, Status, Total, Linked"],
                 ["Products", "BizBox items", "Item, Name, Category, Unit, Unit cost"],
                 ["Invoices", "BizBox receiving records and invoices", "Invoice, Supplier's invoice no., Party, Invoiced, Due, Status, Total, Agreement"],
                 ["Changes to BizBox", "What people have proposed to change", "Change, Record, Field, From → to, Why, Asked by, State"]]),
          UL(["<b>Tiles</b> above Procurement and Invoices count each status BizBox uses and add up its total. The statuses are BizBox's own words; the desk adds none.",
              "<b>Include records gone from BizBox</b> shows records that have left BizBox but are kept because a ticket, project or agreement links to them. They read <i>no longer in BizBox</i>.",
              "<b>Linked</b> shows the tickets, projects and agreements that point at a record, when you may see them.",
              "Every search runs on the reference and the words, like <code>PO-26-0402</code> or <code>Netline</code>."]),
          who=["Finance: Read"]),
        S("fin-po", "Reading Finance", "Purchase orders and products",
          LEAD("A purchase order's page shows BizBox's header, every line, and the work linked to it."),
          FIG("fin-po", "A purchase order: the lines with ordered and received quantities, unit cost and the extended amount, with the lines' total."),
          WIDGET("Check a line total", '<table class="wt"><thead><tr><th>Line</th><th>Ordered</th><th>Unit cost</th><th>Extended</th><th></th></tr></thead><tbody></tbody></table>'
                 '<div class="w-row"><button class="w-btn ghost add">Add a line</button><label style="display:none">Tax<input class="tax" type="number" value="0"></label></div><div class="w-out out"></div>',
                 "quote", {"lines": [["Access switch 48-port PoE", 4, 68000], ["SFP+ module 10G", 8, 4400], ["Patch cord 1m (pack of 24)", 2, 1900]]}),
          P("The desk multiplies ordered quantity by unit cost for each line, exactly as above. The PO's own total is BizBox's figure; where the two differ, BizBox's is the one that counts."),
          FIG("fin-products", "Products: BizBox's item list with category, unit and unit cost."),
          who=["Finance: Read"]),
        S("fin-inv", "Reading Finance", "Invoices",
          LEAD("An invoice's page is BizBox's record, the agreement that covers it, the work linked to it, and any change proposed to it."),
          TOUR("fin-invoice"),
          NOTE("info", "An invoice is <b>Draft</b>, <b>Posted</b> or <b>Cancelled</b>, as BizBox says. The desk cannot know whether it is paid, because BizBox's receiving tables do not say, so it never shows paid or unpaid."),
          who=["Finance: Read"]),
        S("fin-agr", "Agreements", "Agreements",
          LEAD("An agreement is the desk's own record of a deal with a supplier or partner. From it you name the BizBox invoices, purchase orders and products it covers, and the desk adds them up."),
          TOUR("fin-agreement"),
          H("Make one"),
          STEPS(["<b>Finance › Agreements › New agreement.</b> Give it a name, the other party, a start and an end, and an amount with its currency.",
                 "<b>It starts as Draft.</b> Make it active when it is signed.",
                 "<b>Cover what it pays for:</b> on its page, choose Invoice, Purchase order or Product and give the BizBox number. Or, from an invoice's page, pick the agreement and press Add to agreement.",
                 "<b>Read the totals:</b> invoices and purchase orders covered, with their sums, against the agreed amount."]),
          STEPPER("Try the status moves", "DRAFT", {
              "DRAFT": {"label": "Draft", "tone": "grey", "text": "Being written. It can already cover records.", "next": [["ACTIVE", "Make active"], ["CANCELLED", "Cancel", None, True]]},
              "ACTIVE": {"label": "Active", "tone": "green", "text": "In force. This is the normal state.", "next": [["INACTIVE", "Make inactive", None, True], ["CANCELLED", "Cancel", None, True]]},
              "INACTIVE": {"label": "Inactive", "tone": "amber", "text": "Paused or ended, kept for history. It still covers what it covered.", "next": [["ACTIVE", "Make active"], ["CANCELLED", "Cancel", None, True]]},
              "CANCELLED": {"label": "Cancelled", "tone": "red", "text": "Cancelled. A cancelled agreement covers nothing new until it is reopened.", "next": [["DRAFT", "Reopen as draft", None, True]]}}),
          WIDGET("Try it: what an agreement covers", '<div class="w-row"><label>Agreed amount (PHP)<input class="amt" type="number" value="120000"></label></div>'
                 '<table class="wt"><thead><tr><th></th><th>Kind</th><th>BizBox record</th><th>Party</th><th>Amount</th></tr></thead><tbody></tbody></table><div class="w-out out"></div>',
                 "cover", {"items": [["INVOICE", "RR-26-1098", "PrintCare Services", 64000, 1], ["PURCHASE_ORDER", "PO-26-0399", "PrintCare Services", 64000, 1],
                                     ["INVOICE", "RR-26-1102", "Medtek Office Supplies Inc", 42500, 0], ["PRODUCT", "ITM-000412", "Toner cartridge, black", None, 1],
                                     ["PRODUCT", "ITM-000418", "Label roll 50x25mm", None, 1]]}),
          UL(["An agreement ends after it starts; the desk refuses the other way round.",
              "Covering the same record twice does nothing the second time.",
              "Removing a covered record is one button, and it is audited.",
              "Coverings are the desk's own table, so a sync never touches them."]),
          who=["Finance: Write to change", "Read to see"]),
        S("fin-link", "Agreements", "Linking BizBox records to work",
          LEAD("Put the money beside the work: a ticket or a project names the BizBox records it concerns."),
          STEPS(["<b>On a ticket</b>, open the Finance card, choose the kind (purchase order, product, invoice or agreement) and type the BizBox number, for example <code>PO-26-0415</code>.",
                 "<b>On a project</b>, the Finance (BizBox) card does the same; the project page shows each linked record.",
                 "<b>On the record's own page</b>, Work linked to it lists every ticket and project that points at it, for the people who may see them."]),
          FIG("project", "A project with its Finance (BizBox) card linking the purchase order for the new switches."),
          NOTE("info", "Linking needs Finance Read and Work on the ticket's board. A restricted board's tickets stay invisible to anyone who is not its member, even on a BizBox record's page."),
          who=["Technicians", "Service managers"]),
        S("fin-changes", "Changing BizBox", "Proposing a change to BizBox (today)",
          LEAD("When a BizBox record is wrong or out of date, propose the change on the desk. It is recorded with who asked and why, and waits. BizBox itself does not change."),
          TABLE(["Record", "Fields you can propose to change"],
                [["Agreement (from BizBox)", "Status, End date"], ["Purchase order", "Status"], ["Invoice", "Status, Due date"], ["Product", "Name, Unit cost"]]),
          STEPS(["<b>Open the record</b> (an invoice, say) and find Changes to BizBox.",
                 "<b>Pick the field</b>, type the new value, and say <b>why</b>: what the person applying it in BizBox needs to know.",
                 "<b>Press Propose the change.</b> The record now shows <i>1 change(s) waiting for BizBox</i>.",
                 "<b>Someone makes the change in BizBox</b> and marks it done (today that is <code>psaspine bizbox-changes --decide</code> on the host). Or you cancel it.",
                 "<b>The next sync</b> brings BizBox's own value into the mirror."]),
          FIG("fin-changes", "Changes to BizBox: every proposal, its state, and who asked."),
          TABLE(["State", "Means"], [['<span class="st amber">Waiting for BizBox</span>', "Recorded; BizBox has not changed."],
                                     ['<span class="st green">Applied</span>', "Done in BizBox, by a person or (later) by the writer, with BizBox's answer recorded."],
                                     ['<span class="st red">Refused</span>', "BizBox said no (later, by the writer), with its reason recorded."],
                                     ['<span class="st grey">Cancelled</span>', "Withdrawn by a person."]]),
          H("What the desk refuses"),
          UL(["A change with no reason: <i>Say why, so the person who applies it in BizBox knows.</i>",
              "The value BizBox already has: <i>That is the value BizBox already has.</i>",
              "A second change to the same field while one waits: <i>A change to due date is already pending; cancel it first.</i>",
              "A field not in the list above: <i>… is not a field that can be changed on this record.</i>"]),
          who=["Finance: Write"]),
        S("fin-twoway", "Changing BizBox", "The two-way link with BizBox",
          '<p><span class="planned">Planned, not built</span></p>',
          LEAD("Today the desk only reads BizBox. The design already has a second direction: an approved change on the desk is offered to BizBox by a <b>writer</b>, and BizBox's answer comes back. The writer is not switched on, and nothing can reach BizBox until it is."),
          '<div class="flow"><div class="box"><b>1. Propose</b>on the desk, with a reason</div><span class="arrow">→</span>'
          '<div class="box"><b>2. Wait</b>Waiting for BizBox</div><span class="arrow">→</span>'
          '<div class="box on"><b>3. The writer</b>offers it to BizBox</div><span class="arrow">→</span>'
          '<div class="box"><b>4. BizBox answers</b>Applied, or Refused with why</div><span class="arrow">→</span>'
          '<div class="box"><b>5. Next sync</b>the mirror shows BizBox\'s value</div></div>',
          WIDGET("Try it: the two-way link, today and planned",
                 '<div class="w-row"><span style="font-weight:600;font-size:13.5px">Write path</span><div class="switch"><button data-on="0" aria-pressed="true">Off (today)</button><button data-on="1" aria-pressed="false">On (planned)</button></div></div>'
                 '<div class="w-row"><label>Record<select class="rec"></select></label><label>Field<select class="fld"></select></label><label>New value<input class="val" type="text" placeholder="e.g. Posted"></label>'
                 '<label style="flex:1 1 220px">Why<input class="why2" type="text" placeholder="What the person in BizBox needs to know"></label><button class="w-btn prop">Propose the change</button></div>'
                 '<div class="w-row"><button class="w-btn runw" disabled>Run the writer</button><button class="w-btn ghost sync">Run the sync</button></div>'
                 '<div class="w-out msg"></div><div class="log" style="margin-top:10px"></div><h4>The record, in BizBox and on the desk</h4><div class="mirror"></div>',
                 "twoway", {"records": {
                     "RR-26-1155": {"label": "Invoice RR-26-1155", "fields": {"status": ["Status", "text"], "due_on": ["Due date", "date"]},
                                    "biz": {"status": "Draft", "due_on": "2026-10-29"}, "desk": {"status": "Draft", "due_on": "2026-10-29"}},
                     "PO-26-0421": {"label": "Purchase order PO-26-0421", "fields": {"status": ["Status", "text"]},
                                    "biz": {"status": "Draft"}, "desk": {"status": "Draft"}},
                     "ITM-000412": {"label": "Product ITM-000412", "fields": {"name": ["Name", "text"], "unit_cost": ["Unit cost", "money"]},
                                    "biz": {"name": "Toner cartridge, black, HP 58A", "unit_cost": "3450.00"}, "desk": {"name": "Toner cartridge, black, HP 58A", "unit_cost": "3450.00"}}}}),
          H("How it is designed"),
          UL(["<b>Only these fields, ever:</b> the list in the section above. The writer cannot touch anything else.",
              "<b>Off by default.</b> The writer is registered by configuration on the host, never by the desk. Until then every change stays pending, so nothing reaches BizBox by accident.",
              "<b>BizBox decides.</b> Each pending change is offered one at a time. BizBox's own answer is recorded on the change, as Applied or Refused.",
              "<b>The mirror follows BizBox,</b> not the proposal: the next sync shows BizBox's value, so the desk never claims a change BizBox did not make.",
              "<b>Every step is audited</b> as a BizBox change, with who proposed, who or what decided, and when."]),
          H("What switching it on would take"),
          TABLE(["Step", "Whose", "State"],
                [["Decide that the desk may write to BizBox, and for which fields", "Dada, with Finance", "Not decided"],
                 ["A write interface on the BizBox side (a procedure or view that accepts only these fields)", "BizBox and SQL01", "Not built"],
                 ["A writer on the host that calls it, with its own least-privilege login", "SQL01 and Dada IT", "Not built; the desk's side is ready"],
                 ["A test against a copy of BizBox before the live one", "SQL01", "Not done"]]),
          NOTE("warn", "Until every row above is done, treat Changes to BizBox as a to-do list for BizBox, not a way to change it. The desk says so on every record page."),
          who=["Finance: Write", "Administrators"]),
        S("fin-sync", "For administrators", "How the mirror is kept",
          LEAD("One command copies BizBox into the mirror. It is fenced so that nothing but finance data can cross, because BizBox also holds patient records."),
          STEPS(["<b>A map file</b> names the BizBox views and columns to read. Nothing is discovered at run time.",
                 "<b>Every name must be a plain identifier:</b> no brackets, quotes, spaces or semicolons, so a map cannot carry SQL.",
                 "<b>A name that looks like a patient field is refused</b>: patient, admission, diagnosis, PhilHealth, case number, birth date and the like.",
                 "<b>The login must not be the SQL administrator</b> and asks for read-only access; the host's read-only views are SQL01's.",
                 "<b>Preview first.</b> <code>psaspine sync-bizbox</code> shows what would change; <code>--apply</code> writes the mirror."]),
          CHOOSER("What happens to a record when…", [
              ("new", "BizBox has a new PO", "The next sync adds it to Procurement, counted in the banner as new."),
              ("chg", "BizBox changes an invoice's status", "The next sync updates the mirror, counted as changed. Any proposal about that field keeps its own state."),
              ("gone", "A record leaves BizBox", "It is marked absent. If a ticket, project or agreement links to it, it is kept and reads <i>no longer in BizBox</i>; otherwise it drops out of the lists."),
              ("never", "Nobody has run a sync", "Finance says <i>Not synced yet</i> and the lists are empty.")]),
          who=["Administrators", "SQL01"]),
        S("fin-sales", "Related", "Where Sales fits",
          LEAD("A won sales opportunity drafts an agreement from its accepted quote, so the work it brings is covered from day one."),
          P(f'The Sales guide explains opportunities, quotes and the pipeline: <a href="{fname("Sales")}">open the Sales guide</a>.'),
          who=["Service managers"]),
        S("fin-faq", "Reference", "Questions people ask",
          DET([("Can I mark an invoice as paid?", "No. BizBox's tables do not say whether an invoice is paid, so the desk shows only BizBox's own status: Draft, Posted or Cancelled."),
               ("I changed a value and BizBox still shows the old one.", "That is expected today. A proposal waits until someone makes the change in BizBox and marks it done, or until the planned write path is switched on. The next sync then shows BizBox's value."),
               ("Why can I not see a ticket linked to this PO?", "Links show only to people who may see the ticket or project. A restricted board's tickets are for its members only."),
               ("The numbers here differ from BizBox.", "Look at Last synced at the top of Finance. The mirror is as of that moment; ask for a sync if it is old."),
               ("Can an agreement cover a record from another supplier?", "Yes; the desk does not check the party. Cover what the agreement pays for, and use the note to say why."),
               ("Who can change agreements?", "Anyone whose role gives Finance Write. That list is Dada's decision in Setup › Security roles.")])),
        S("fin-quiz", "Reference", "Check yourself", QUIZ()),
    ])


